# unityHPC/job_template.sh (gpu) — generated by /unity-hpc:setup. Do not hand-edit.
# Single-node, single-or-multi-GPU. run.sh emits the #SBATCH header above this and
# exports EXP, REMOTE_DIR and JOB_COMMAND.
set -euo pipefail

REMOTE_DIR="${REMOTE_DIR/#\~/$HOME}"
cd "$REMOTE_DIR"

export PYTHONUNBUFFERED=1
export OMP_NUM_THREADS="${SLURM_CPUS_PER_TASK:-1}"

set +u
[[ -f /usr/share/lmod/lmod/init/bash ]] && . /usr/share/lmod/lmod/init/bash
set -u
if [ -n "${MODULES:-}" ]; then
    module purge && module load ${MODULES}
fi

if [ -n "${VENV_PATH:-}" ] && [ -f "${VENV_PATH}/bin/activate" ]; then
    . "${VENV_PATH}/bin/activate"
fi

GPU_NAME=$(nvidia-smi --query-gpu=name --format=csv,noheader 2>/dev/null | head -1 || echo "unknown")
echo "=== $(date -u +%Y-%m-%dT%H:%M:%SZ) | exp=${EXP} | host=$(hostname) | gpu=${GPU_NAME} ==="

set +e
eval "$JOB_COMMAND"
RC=$?
set -e
echo "=== done $(date -u +%Y-%m-%dT%H:%M:%SZ) rc=${RC} ==="
exit "$RC"
